    for r in range(h):
        for c in range(w):
            if grid[r][c] in (1, 6):
                pts.setdefault(grid[r][c], []).append((r, c))

    # Join aligned pairs of 1s along their diagonal.
    ones = pts.get(1, [])
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) == abs(dc) and dr != 0:
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                r, c = r1, c1
                while True:
                    out[r][c] = 1
                    if (r, c) == (r2, c2):
                        break
                    r += sr
                    c += sc

    sixes = pts.get(6, [])
    # In cases with a single 6 on the 1-diagonal, extend its perpendicular diagonal.
    if len(sixes) == 1 and len(ones) >= 2:
        r, c = sixes[0]
        on_one_diag = any(abs(r-a) == abs(c-b) for a, b in ones)
