        for r2, c2 in ones[i + 1:]:
            if r1 != r2 and abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                points = []
                r, c = r1, c1
                while True:
                    points.append((r, c))
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc
                segments.append((points, dr, dc))
                for r, c in points:
                    out[r][c] = 1

    # A 6 on a 1-segment draws a full diagonal perpendicular to that segment.
    for points, dr, dc in segments:
        point_set = set(points)
        for r, c in sixes:
            if (r, c) not in point_set:
                continue
            sr, sc = dr, -dc
            rr, cc = r, c
            while 0 <= rr - sr < h and 0 <= cc - sc < w:
                rr -= sr
                cc -= sc
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == bg or grid[rr][cc] == 6:
                    out[rr][cc] = 6
                rr += sr
                cc += sc

    return out
